        var v = (ak_dvt_ListMetricsResponse*)NativeMemory.AllocZeroed((nuint)sizeof(ak_dvt_ListMetricsResponse));
        v->utf8_skip = AkUtf8Skip.ListMetricsResponse_ALL;   // D20: every bit set, G.Str validates (strict)
        v->apply = &ApplyRoot;
        v->new_batches = &New_batches;
        v->apply_batches = &Apply_batches;
        v->add_batches_ticks = &Add_batches_ticks;
        v->add_batches_values = &Add_batches_values;
        v->add_batches_codes = &Add_batches_codes;
        v->add_batches_flags = &Add_batches_flags;
        v->add_batches_statuses = &Add_batches_statuses;
        return v;
    }
    /// Step 5b: the pull family's bits, once per root in native memory (the setter copies them).
    private static readonly ak_pvt_ListMetricsResponse* Pvt = MakePvt();
    private static ak_pvt_ListMetricsResponse* MakePvt() { var v = (ak_pvt_ListMetricsResponse*)NativeMemory.AllocZeroed((nuint)sizeof(ak_pvt_ListMetricsResponse)); v->utf8_skip = AkUtf8Skip.ListMetricsResponse_ALL; return v; }
    private int DecodeArmed(byte[] src, int len, int mode, out ListMetricsResponse result)
    {
        result = null;
        EnsureDec();
        // Step a2 (i): no ak_dec_err_reset / ak_dec_err: ak_decode_* clears the context's
        // sticky slot on entry and returns it (a host failure reported through ak_fail
        // from a reverse call included), so its return value carries every error.
        int ar = ArmFor(mode);
        if (ar != 0) { Disarm(ar); return ar; }
        var target = new ListMetricsResponse();
        // D26: the decode host context's ONE GCHandle (allocated with it) reaches it; the
        // call's root is set on it here and cleared after the call.
        var h = _dh;
        h.Root = target;
        int rc = Abi.AK_ERR_HOST;
        try
        {
            fixed (byte* b0 = src)
            fixed (byte* one = One)
            {
                // (NULL, 0) is never handed to the core: an empty buffer is a valid pointer and 0.
                byte* b = len == 0 ? one : b0;
                h.Run->Buf = b;
                _fwd++;
                rc = Abi.ak_decode_ListMetricsResponse(h.Ctx, h.Run, b, (nuint)len, Vt);
            }
        }
        finally { h.Root = null; h.Run->Buf = null; rc = Disarm(rc); }
        if (rc < 0) return rc;
        result = target;
        return 0;
    }

    /// D21 s8 attribution (HARNESS ONLY): the same push decode through another vtable.
    /// kind 0 `parse`: every callback null but `new_<slot>` (NewZero: the core skips a non-leaf
    /// element whose `new_` is null), utf8_skip all bits (as the reference); kind 1 `noop`:
    /// every callback G.Noop (new_: NewZero); kind 2 `parse-validate`: kind 0 with utf8_skip 0
    /// (the core validates every string).
    public static readonly ak_dvt_ListMetricsResponse* VtParse = MakeVtAttr(0), VtNoop = MakeVtAttr(1), VtParseValidate = MakeVtAttr(2);
    private static ak_dvt_ListMetricsResponse* MakeVtAttr(int kind)
    {
        var v = (ak_dvt_ListMetricsResponse*)NativeMemory.AllocZeroed((nuint)sizeof(ak_dvt_ListMetricsResponse));
        v->utf8_skip = kind == 2 ? 0 : AkUtf8Skip.ListMetricsResponse_ALL;
        if (kind == 1) *(void**)&v->apply = G.NoopPtr;
        *(void**)&v->new_batches = G.NewZeroPtr;
        if (kind == 1) *(void**)&v->apply_batches = G.NoopPtr;
        if (kind == 1) *(void**)&v->add_batches_ticks = G.NoopPtr;
        if (kind == 1) *(void**)&v->add_batches_values = G.NoopPtr;
        if (kind == 1) *(void**)&v->add_batches_codes = G.NoopPtr;
        if (kind == 1) *(void**)&v->add_batches_flags = G.NoopPtr;
        if (kind == 1) *(void**)&v->add_batches_statuses = G.NoopPtr;
        return v;
    }
    /// D21 s8 attribution (HARNESS ONLY): DecodeArmed through `vt`; the graph is the bare
    /// root (the callbacks build nothing) and buffers the callbacks did not take are not
    /// UNDELIVERED here (the arena rewinds at the next decode).
    public int DecodeVt(byte[] src, int len, bool retain, ak_dvt_ListMetricsResponse* vt)
    {
        EnsureDec();
        int ar = ArmFor(retain ? -1 : -2);
        if (ar != 0) { Disarm(ar); return ar; }
        int rc;
        fixed (byte* b0 = src)
        fixed (byte* one = One)
        {
            byte* b = len == 0 ? one : b0;
            _dh.Run->Buf = b;
            rc = Abi.ak_decode_ListMetricsResponse(_dh.Ctx, _dh.Run, b, (nuint)len, vt);
            _dh.Run->Buf = null;
        }
        rc = Disarm(rc);
        return rc == UNDELIVERED ? 0 : rc;
    }
    /// D21 s8 attribution (HARNESS ONLY): the pull family's parse alone (no replay).
    public int ParseOnly(byte[] src, int len, bool retain)
    {
        EnsureDec();
        int ar = ArmFor(retain ? -1 : -2);
        if (ar != 0) { Disarm(ar); return ar; }
        int rc;
        fixed (byte* b0 = src)
        fixed (byte* one = One)
            rc = Abi.ak_parse_ListMetricsResponse(_dh.Ctx, len == 0 ? one : b0, (nuint)len);
        rc = Disarm(rc);
        return rc == UNDELIVERED ? 0 : rc;
    }

    /// ABI v1 7.1's PULL family: parse into the context's record stream (no reverse
    /// call but grow), then replay it with the same group readers the push callbacks
    /// use. The context is armed exactly as for push.
    public ListMetricsResponse Pull(byte[] src, int len) { int rc = TryPull(src, len, false, out var t); if (rc < 0) throw new InvalidOperationException($"core parse failed: {rc}"); return t; }
    public ListMetricsResponse PullU(byte[] src, int len) { int rc = TryPull(src, len, true, out var t); if (rc < 0) throw new InvalidOperationException($"core parse failed: {rc}"); return t; }

    public int TryPull(byte[] src, int len, bool retain, out ListMetricsResponse result)
    {
        result = null;
        EnsureDec();
        int ar = ArmFor(retain ? -1 : -2);
        if (ar != 0) { Disarm(ar); return ar; }
        var t = new ListMetricsResponse();
        int rc = Abi.AK_ERR_HOST;
        try
        {
            fixed (byte* b0 = src)
            fixed (byte* one = One)
            {
                byte* b = len == 0 ? one : b0;
                _fwd++;
                rc = Abi.ak_parse_ListMetricsResponse(_dh.Ctx, b, (nuint)len);
                if (rc >= 0)
                {
                    byte* recs; nuint rlen;
                    _fwd++;
                    rc = Abi.ak_bdr_ptr(_dh.Ctx, &recs, &rlen);
                    if (rc == 0) { try { Replay(t, b, recs, (int)rlen, _dh.Run->Arena); } catch (DecoderFallbackException) { rc = Abi.AK_ERR_TRANSCODE; } }
                }
            }
        }
        finally { rc = Disarm(rc); }
        if (rc < 0) return rc;
        result = t;
        return 0;
    }

    private const uint OP_APPLY = 1, OP_ADD = 2, OP_NEW = 3, OP_APPLY_ELEM = 4;   // ak_bdr_rec.op
    private static void Replay(ListMetricsResponse t, byte* b, byte* p, int len, UnkArena* a)
    {
        int at = 0;
        while (len - at >= sizeof(ak_bdr_rec))
        {
            ref var r = ref *(ak_bdr_rec*)(p + at);
            byte* body = p + at + sizeof(ak_bdr_rec);
            at += sizeof(ak_bdr_rec) + (int)r.bytes;
            uint outer = r.slot >> 16, inner = r.slot & 0xFFFF;
            switch (r.op)
            {
                case OP_APPLY: G.D_ListMetricsResponse(ref *(ak_dfix_ListMetricsResponse*)body, t, b, a); break;
                case OP_NEW when outer == 1: t.Batches.Add(new MetricsBatch()); break;
                case OP_APPLY_ELEM when outer == 1: G.D_MetricsBatch(ref *(ak_dfix_MetricsBatch*)body, t.Batches[(int)r.token], b, a); break;
                case OP_ADD when outer == 1 && inner == 1:
                {
                    var xs = (long*)body; var e = t.Batches[(int)r.token]; var il = e.Ticks;
                    il.EnsureCapacity(il.Count + (int)r.n);   // step 9a: the run's count is known
                    for (int k = 0; k < (int)r.n; k++) il.Add(xs[k]);
                    break;
                }
                case OP_ADD when outer == 1 && inner == 2:
                {
                    var xs = (double*)body; var e = t.Batches[(int)r.token]; var il = e.Values;
                    il.EnsureCapacity(il.Count + (int)r.n);   // step 9a: the run's count is known
                    for (int k = 0; k < (int)r.n; k++) il.Add(xs[k]);
                    break;
                }
                case OP_ADD when outer == 1 && inner == 3:
                {
                    var xs = (int*)body; var e = t.Batches[(int)r.token]; var il = e.Codes;
                    il.EnsureCapacity(il.Count + (int)r.n);   // step 9a: the run's count is known
                    for (int k = 0; k < (int)r.n; k++) il.Add(xs[k]);
                    break;
                }
                case OP_ADD when outer == 1 && inner == 4:
                {
                    var xs = (byte*)body; var e = t.Batches[(int)r.token]; var il = e.Flags;
                    il.EnsureCapacity(il.Count + (int)r.n);   // step 9a: the run's count is known
                    for (int k = 0; k < (int)r.n; k++) il.Add((xs[k] != 0));
                    break;
                }
                case OP_ADD when outer == 1 && inner == 5:
                {
                    var xs = (int*)body; var e = t.Batches[(int)r.token]; var il = e.Statuses;
                    il.EnsureCapacity(il.Count + (int)r.n);   // step 9a: the run's count is known
                    for (int k = 0; k < (int)r.n; k++) il.Add((TaskStatus)xs[k]);
                    break;
                }
                default: break;
            }
        }
    }

    /// FIX-PLAN D23: the FSM decode family. ak_fsm_begin_ListMetricsResponse returns
    /// the first event, ak_fsm_next_ListMetricsResponse each next one, each RETURNING
    /// the event's op (> 0; the root APPLY is the last, the end) or an error (< 0);
    /// every event is consumed (FsmDispatch) before the next call, which may overwrite
    /// its payload. One `fixed` spans begin and every next (the core holds spans into
    /// the input until the end event). Arming, Disarm, retain ownership and the failure
    /// path are pull's; a failed decode's partial object is discarded.
    public ListMetricsResponse Fsm(byte[] src, int len) { int rc = TryFsm(src, len, false, out var t); if (rc < 0) throw new InvalidOperationException($"core FSM decode failed: {rc}"); return t; }
    public ListMetricsResponse FsmU(byte[] src, int len) { int rc = TryFsm(src, len, true, out var t); if (rc < 0) throw new InvalidOperationException($"core FSM decode failed: {rc}"); return t; }
    /// D23: the FSM's own D20 mask (every bit: G.Str validates), native, copied by its setter
    /// (ak_fsm_set_pvt_<Root>) once, when EnsureDec creates the context.
    private static readonly ak_pvt_ListMetricsResponse* FsmPvt = MakeFsmPvt();
    private static ak_pvt_ListMetricsResponse* MakeFsmPvt() { var v = (ak_pvt_ListMetricsResponse*)NativeMemory.AllocZeroed((nuint)sizeof(ak_pvt_ListMetricsResponse)); v->utf8_skip = AkUtf8Skip.ListMetricsResponse_ALL; return v; }

    public int TryFsm(byte[] src, int len, bool retain, out ListMetricsResponse result)
    {
        result = null;
        EnsureDec();
        int ar = ArmFor(retain ? -1 : -2);
        if (ar != 0) { Disarm(ar); return ar; }
        var t = new ListMetricsResponse();
        int rc = Abi.AK_ERR_HOST;
        try
        {
            fixed (byte* b0 = src)
            fixed (byte* one = One)
            {
                byte* b = len == 0 ? one : b0;
                ak_fsm_ev ev;
                _fwd++;
                UnkArena* a = _dh.Run->Arena;
                int op = Abi.ak_fsm_begin_ListMetricsResponse(_dh.Ctx, b, (nuint)len, &ev);
                try
                {
                    while (op > 0)
                    {
                        if (op == (int)Abi.AK_BDR_APPLY)
                        {
                            // The root group: always the last event, the end.
                            G.D_ListMetricsResponse(ref *(ak_dfix_ListMetricsResponse*)ev.data, t, b, a);
                            break;
                        }
                        FsmDispatch(t, b, (uint)op, &ev, a);
                        _fwd++;
                        op = Abi.ak_fsm_next_ListMetricsResponse(_dh.Ctx, &ev);
                    }
                    rc = op < 0 ? op : 0;
                }
                catch (DecoderFallbackException) { rc = Abi.AK_ERR_TRANSCODE; }
            }
        }
        finally { rc = Disarm(rc); }
        if (rc < 0) return rc;   // the partial object is dropped
        result = t;
        return 0;
    }

    /// D23: one non-final event, `op` the call's return (NEW, ADD, APPLY_ELEM; the root APPLY is the end event,
    /// handled by TryFsm). slot = outer << 16 | inner, pull's numbering: a root-level run
    /// is (0, slot), a non-leaf slot's element is (slot, 0) and its inner runs (slot, inner).
    private static void FsmDispatch(ListMetricsResponse t, byte* b, uint op, ak_fsm_ev* ev, UnkArena* a)
    {
        byte* d = (byte*)ev->data;
        switch (op)
        {
            case Abi.AK_BDR_NEW:
                switch (ev->slot >> 16)
                {
                    case 1: t.Batches.Add(new MetricsBatch()); return;
                }
                return;
            case Abi.AK_BDR_APPLY_ELEM:
                switch (ev->slot >> 16)
                {
                    case 1: G.D_MetricsBatch(ref *(ak_dfix_MetricsBatch*)d, t.Batches[(int)ev->token], b, a); return;
                }
                return;
            case Abi.AK_BDR_ADD:
                switch (ev->slot)
                {
                    case 65537u:   // slot 1's element, inner run 1
                    {
                        var xs = (long*)d; var e = t.Batches[(int)ev->token]; var il = e.Ticks; int n = (int)ev->n;
                        il.EnsureCapacity(il.Count + n);
                        for (int k = 0; k < n; k++) il.Add(xs[k]);
                        return;
                    }
                    case 65538u:   // slot 1's element, inner run 2
                    {
                        var xs = (double*)d; var e = t.Batches[(int)ev->token]; var il = e.Values; int n = (int)ev->n;
                        il.EnsureCapacity(il.Count + n);
                        for (int k = 0; k < n; k++) il.Add(xs[k]);
                        return;
                    }
                    case 65539u:   // slot 1's element, inner run 3
                    {
                        var xs = (int*)d; var e = t.Batches[(int)ev->token]; var il = e.Codes; int n = (int)ev->n;
                        il.EnsureCapacity(il.Count + n);
                        for (int k = 0; k < n; k++) il.Add(xs[k]);
                        return;
                    }
                    case 65540u:   // slot 1's element, inner run 4
                    {
                        var xs = (byte*)d; var e = t.Batches[(int)ev->token]; var il = e.Flags; int n = (int)ev->n;
                        il.EnsureCapacity(il.Count + n);
                        for (int k = 0; k < n; k++) il.Add((xs[k] != 0));
                        return;
                    }
                    case 65541u:   // slot 1's element, inner run 5
                    {
                        var xs = (int*)d; var e = t.Batches[(int)ev->token]; var il = e.Statuses; int n = (int)ev->n;
                        il.EnsureCapacity(il.Count + n);
                        for (int k = 0; k < n; k++) il.Add((TaskStatus)xs[k]);
                        return;
                    }
                }
                return;
        }
    }

    public long PullFootprint() => _dh == null ? 0 : (long)Abi.ak_bdr_footprint(_dh.Ctx);
    public AkCounters EncCounters() { AkCounters c; Abi.ak_enc_counters(_ctx, &c); return c; }
    public void EncCountersReset() => Abi.ak_enc_counters_reset(_ctx);
    public AkCounters DecCounters() { AkCounters c; if (_dh == null) return default; Abi.ak_dec_counters(_dh.Ctx, &c); return c; }
    public void DecCountersReset() { if (_dh != null) Abi.ak_dec_counters_reset(_dh.Ctx); }

    public void Dispose()
    {
        _eh.Dispose();
        _dh?.Dispose(); _dh = null;
        if (_evt_batches != null) { NativeMemory.Free(_evt_batches); _evt_batches = null; }
    }
}

[StructLayout(LayoutKind.Sequential)]
/// The encode host context's native block (D26: CoreFfi_DualResponse.EncCtx owns it), the loop
/// callbacks' `obj`: Host is the ONE GCHandle to the managed context, Defer the call's
/// E1R / E1C mode (0 when the frames do not run), then the staged element arrays.
public unsafe struct Run_DualResponse
{
    public IntPtr Host;
    public int Defer;
    public int Chunk;
    public int Retain;
    public void* S_left; public int N_left;
    public void* S_right; public int N_right;
}

/// core-ffi for `DualResponse`: every group, slot and entry point from the plan.
public sealed unsafe class CoreFfi_DualResponse : IDisposable
{
    /// D26 (s15): the host's explicit contexts. _eh, created with the binding, owns the core
    /// encode context; _dh, created on the first decode, owns the core decode context.
    private readonly EncCtx _eh;
    private DecCtx _dh;
    private IntPtr _ctx => _eh.Ctx;
    private Stage _st => _eh.St;
    public int Chunk;
    /// Counted where each crossing happens (R5). Process-wide (not per thread, not per
    /// context): one arm at a time.
    private static long _fwd, _rev;
    public long ForwardCalls => _fwd;
    public long ReverseCalls => _rev;
    public void CallsReset() { _fwd = 0; _rev = 0; _resets = 0; }
    private int _cap_left;
    private int _cap_right;

    public CoreFfi_DualResponse(bool utf16 = false)
    {
        _eh = new EncCtx(utf16 || Environment.GetEnvironmentVariable("AK_UTF16") == "1");
    }

    /// D26 (s15): the host's explicit ENCODE context, one per binding instance, created with it:
    /// it OWNS the core encode context (ak_enc_ctx), the native block Run_DualResponse (the loop
    /// callbacks' `obj`: its Host word is the ONE GCHandle to this object, allocated in EncHost's
    /// constructor, never per call) and, through EncHost, the staging Stage (string and bytes
    /// staging, E2's string table, E1C's handle list, the guard counters, the stack probe). Per
    /// call (Go): the core context and the staging are reset; under E1R / E1C, Root and
    /// Run->Defer are set for the call and cleared after it. Freed in Dispose.
    private sealed class EncCtx : EncHost
    {
        public IntPtr Ctx;
        public Run_DualResponse* Run;
        public DualResponse Root;
        public EncCtx(bool utf16) : base(utf16)
        {
            Ctx = Abi.ak_enc_ctx_new();
            if (Ctx == IntPtr.Zero) throw new InvalidOperationException("ak_enc_ctx_new returned null");
            Run = (Run_DualResponse*)NativeMemory.AllocZeroed((nuint)sizeof(Run_DualResponse));
            Run->Host = Handle;
        }
        public override void Dispose()
        {
            if (Ctx != IntPtr.Zero) { Abi.ak_enc_ctx_free(Ctx); Ctx = IntPtr.Zero; }
            if (Run != null)
            {
                NativeMemory.Free(Run->S_left);
                NativeMemory.Free(Run->S_right);
                NativeMemory.Free(Run); Run = null;
            }
            Root = null;
            base.Dispose();
        }
    }

    /// D26: the loop callbacks reach the encode host context through `obj` (its Run block).
    private static EncCtx Host(Run_DualResponse* run) => (EncCtx)GCHandle.FromIntPtr(run->Host).Target;

    /// E1R: one frame per element of the chunk [off, off + k); each `fixed`s every string of
    /// its element, patches the element's marked members, and recurses; the deepest frame
    /// makes the element call, and unwinding releases the pins.
    private static int Rec_left(IntPtr ctx, Run_DualResponse* run, Stage st, System.Collections.Generic.List<Pair> lst, int off, int k, int i)
    {
#if AK_HOST_COUNT
        st.Sp(i, (byte*)&i);
#endif
        if (i == k)
        {
            _fwd++;
            return run->Retain != 0 ? Abi.ak_uelem_Pair(ctx, (ak_ufix_Pair*)((ak_ufix_Pair*)run->S_left + off), k) : Abi.ak_elem_Pair(ctx, (ak_efix_Pair*)((ak_efix_Pair*)run->S_left + off), k);
        }
        var __e = lst[off + i];
        fixed (char* __p0 = __e.Key)
        {
            if (run->Retain != 0)
            {
                var __g = (ak_ufix_Pair*)run->S_left + off + i;
                if (__g->key.data == Stage.PinPending) { __g->key.data = (IntPtr)__p0; if (!Stage.NoGuard) { st.Patched++; } }
            }
            else
            {
                var __g = (ak_efix_Pair*)run->S_left + off + i;
                if (__g->key.data == Stage.PinPending) { __g->key.data = (IntPtr)__p0; if (!Stage.NoGuard) { st.Patched++; } }
            }
            return Rec_left(ctx, run, st, lst, off, k, i + 1);
        }
    }

    /// E1C: the chunk's strings pinned by GCHandles, freed once its element call has returned.
    private static int ChunkH_left(IntPtr ctx, Run_DualResponse* run, Stage st, System.Collections.Generic.List<Pair> lst, int off, int k)
    {
        int __h = st.ChunkMark();   // this chunk releases only the handles it adds
        for (int i = 0; i < k; i++)
        {
            var __e = lst[off + i];
            if (run->Retain != 0)
            {
                var __g = (ak_ufix_Pair*)run->S_left + off + i;
                if (__g->key.data == Stage.PinPending) { __g->key.data = st.PinChunk(__e.Key); }
            }
            else
            {
                var __g = (ak_efix_Pair*)run->S_left + off + i;
                if (__g->key.data == Stage.PinPending) { __g->key.data = st.PinChunk(__e.Key); }
            }
        }
        st.BeforeChunkCall(__h);
        _fwd++;
        int rc = run->Retain != 0 ? Abi.ak_uelem_Pair(ctx, (ak_ufix_Pair*)((ak_ufix_Pair*)run->S_left + off), k) : Abi.ak_elem_Pair(ctx, (ak_efix_Pair*)((ak_efix_Pair*)run->S_left + off), k);
        st.ReleaseChunk(__h);
        return rc;
    }

    [UnmanagedCallersOnly(CallConvs = new[] { typeof(CallConvCdecl) })]
    private static int Loop_left(IntPtr ctx, void* obj, long token)
    {
        _rev++;
        try
        {
            var run = (Run_DualResponse*)obj;
            int n = run->N_left;
            if (n == 0) return 0;
            int chunk = run->Chunk <= 0 ? n : run->Chunk;
            int d = run->Defer;
            EncCtx h = null;
            if (d != 0) { h = Host(run); if (chunk > Stage.PinK) chunk = Stage.PinK; }
            for (int off = 0; off < n; off += chunk)
            {
                int k = n - off; if (k > chunk) k = chunk;
                if (d != 0)
                {
                    int rp = d == 1 ? Rec_left(ctx, run, h.St, h.Root.Left, off, k, 0) : ChunkH_left(ctx, run, h.St, h.Root.Left, off, k);
                    Stage.AfterChunk();
                    if (rp < 0) return rp;
                    continue;
                }
                _fwd++;
                int rc = run->Retain != 0
                    ? Abi.ak_uelem_Pair(ctx, (ak_ufix_Pair*)((ak_ufix_Pair*)run->S_left + off), k)
                    : Abi.ak_elem_Pair(ctx, (ak_efix_Pair*)((ak_efix_Pair*)run->S_left + off), k);
                if (rc < 0) return rc;
            }
            return 0;
        }
        catch { return Abi.AK_ERR_HOST; }
    }

    /// E1R: one frame per element of the chunk [off, off + k); each `fixed`s every string of
    /// its element, patches the element's marked members, and recurses; the deepest frame
    /// makes the element call, and unwinding releases the pins.
    private static int Rec_right(IntPtr ctx, Run_DualResponse* run, Stage st, System.Collections.Generic.List<Pair> lst, int off, int k, int i)
    {
#if AK_HOST_COUNT
        st.Sp(i, (byte*)&i);
#endif
        if (i == k)
        {
            _fwd++;
            return run->Retain != 0 ? Abi.ak_uelem_Pair(ctx, (ak_ufix_Pair*)((ak_ufix_Pair*)run->S_right + off), k) : Abi.ak_elem_Pair(ctx, (ak_efix_Pair*)((ak_efix_Pair*)run->S_right + off), k);
        }
        var __e = lst[off + i];
        fixed (char* __p0 = __e.Key)
        {
            if (run->Retain != 0)
            {
                var __g = (ak_ufix_Pair*)run->S_right + off + i;
                if (__g->key.data == Stage.PinPending) { __g->key.data = (IntPtr)__p0; if (!Stage.NoGuard) { st.Patched++; } }
            }
            else
            {
                var __g = (ak_efix_Pair*)run->S_right + off + i;
                if (__g->key.data == Stage.PinPending) { __g->key.data = (IntPtr)__p0; if (!Stage.NoGuard) { st.Patched++; } }
            }
            return Rec_right(ctx, run, st, lst, off, k, i + 1);
        }
    }

    /// E1C: the chunk's strings pinned by GCHandles, freed once its element call has returned.
    private static int ChunkH_right(IntPtr ctx, Run_DualResponse* run, Stage st, System.Collections.Generic.List<Pair> lst, int off, int k)
    {
        int __h = st.ChunkMark();   // this chunk releases only the handles it adds
        for (int i = 0; i < k; i++)
        {
            var __e = lst[off + i];
            if (run->Retain != 0)
            {
                var __g = (ak_ufix_Pair*)run->S_right + off + i;
                if (__g->key.data == Stage.PinPending) { __g->key.data = st.PinChunk(__e.Key); }
            }
            else
            {
                var __g = (ak_efix_Pair*)run->S_right + off + i;
                if (__g->key.data == Stage.PinPending) { __g->key.data = st.PinChunk(__e.Key); }
            }
        }
        st.BeforeChunkCall(__h);
        _fwd++;
        int rc = run->Retain != 0 ? Abi.ak_uelem_Pair(ctx, (ak_ufix_Pair*)((ak_ufix_Pair*)run->S_right + off), k) : Abi.ak_elem_Pair(ctx, (ak_efix_Pair*)((ak_efix_Pair*)run->S_right + off), k);
        st.ReleaseChunk(__h);
        return rc;
    }

    [UnmanagedCallersOnly(CallConvs = new[] { typeof(CallConvCdecl) })]
    private static int Loop_right(IntPtr ctx, void* obj, long token)
    {
        _rev++;
        try
        {
            var run = (Run_DualResponse*)obj;
            int n = run->N_right;
            if (n == 0) return 0;
            int chunk = run->Chunk <= 0 ? n : run->Chunk;
            int d = run->Defer;
            EncCtx h = null;
            if (d != 0) { h = Host(run); if (chunk > Stage.PinK) chunk = Stage.PinK; }
            for (int off = 0; off < n; off += chunk)
            {
                int k = n - off; if (k > chunk) k = chunk;
                if (d != 0)
                {
                    int rp = d == 1 ? Rec_right(ctx, run, h.St, h.Root.Right, off, k, 0) : ChunkH_right(ctx, run, h.St, h.Root.Right, off, k);
                    Stage.AfterChunk();
                    if (rp < 0) return rp;
                    continue;
                }
                _fwd++;
                int rc = run->Retain != 0
                    ? Abi.ak_uelem_Pair(ctx, (ak_ufix_Pair*)((ak_ufix_Pair*)run->S_right + off), k)
                    : Abi.ak_elem_Pair(ctx, (ak_efix_Pair*)((ak_efix_Pair*)run->S_right + off), k);
                if (rc < 0) return rc;
            }
            return 0;
        }
        catch { return Abi.AK_ERR_HOST; }
    }

    public int Fill(DualResponse src) { Go(src, false, false, out _, out _); return 0; }
    public void Encode(DualResponse src, out byte* p, out int len) { int rc = Go(src, false, true, out p, out len); if (rc < 0) throw new InvalidOperationException($"core encode failed: {rc}"); }
    public void EncodeU(DualResponse src, out byte* p, out int len) { int rc = Go(src, true, true, out p, out len); if (rc < 0) throw new InvalidOperationException($"core encode failed: {rc}"); }
    public int TryEncode(DualResponse src, bool retain, out byte* p, out int len) => Go(src, retain, true, out p, out len);
    /// ABI v1 section 9's move path (WP8): encode and leave the output IN the encode context,
    /// no ak_enc_take, for ak_call_unary_enc / ak_call_send_enc to move as the request body.
    public int EncodeInto(DualResponse src, bool retain)
    {
        _keep = true;
        try { return Go(src, retain, true, out _, out _); }
        finally { _keep = false; }
    }
    /// A copy of the bytes an EncodeInto left in the context (ak_enc_take reads them without
    /// consuming them); for checks, never on a timed path.
    public byte[] ContextBytes()
    {
        byte* bp; nuint blen;
        int tk = Abi.ak_enc_take(_ctx, &bp, &blen);
        if (tk != 0) throw new InvalidOperationException($"core encode failed: {tk}");
        return new ReadOnlySpan<byte>(bp, (int)blen).ToArray();
    }
    /// The encode context, for the move path's entries.
    public IntPtr EncContext => _ctx;
    private bool _keep;
    public byte[] EncodeToArray(DualResponse src, bool retain = false)
    {
        int rc = Go(src, retain, true, out byte* p, out int len);
        if (rc < 0) throw new InvalidOperationException($"core encode failed: {rc}");
        var a = new byte[len];
        new ReadOnlySpan<byte>(p, len).CopyTo(a);
        return a;
    }

    private int Go(DualResponse src, bool retain, bool call, out byte* outPtr, out int outLen)
    {
        outPtr = null; outLen = 0;
        // D26: the call's state is the encode host context's, reset here (the core context
        // with it), reused across calls.
        var __h = _eh;
        IntPtr _ctx = __h.Ctx;
        Stage _st = __h.St;
        Run_DualResponse* _run = __h.Run;
        Abi.ak_enc_reset(_ctx);
        _st.Reset();
        int __d = Stage.Defer;   // E1R / E1C: read once; the default path tests this local only
        _run->Chunk = Chunk;
        _run->Retain = retain ? 1 : 0;
        {
            var lst = src.Left;
            int n = lst == null ? 0 : lst.Count;
            _run->N_left = n;
            Arr.Ensure(ref _run->S_left, ref _cap_left, n, Math.Max(sizeof(ak_efix_Pair), sizeof(ak_ufix_Pair)));
            for (int i = 0; i < n; i++)
            {
                if (retain) G.U_Pair(ref ((ak_ufix_Pair*)_run->S_left)[i], lst[i], _st);
                else G.E_Pair(ref ((ak_efix_Pair*)_run->S_left)[i], lst[i], _st);
            }
        }
        {
            var lst = src.Right;
            int n = lst == null ? 0 : lst.Count;
            _run->N_right = n;
            Arr.Ensure(ref _run->S_right, ref _cap_right, n, Math.Max(sizeof(ak_efix_Pair), sizeof(ak_ufix_Pair)));
            for (int i = 0; i < n; i++)
            {
                if (retain) G.U_Pair(ref ((ak_ufix_Pair*)_run->S_right)[i], lst[i], _st);
                else G.E_Pair(ref ((ak_efix_Pair*)_run->S_right)[i], lst[i], _st);
            }
        }
        var vt = new ak_evt_DualResponse
        {
            loop_left = &Loop_left,
            loop_right = &Loop_right,
        };
        nint rc;
        if (retain)
        {
            var fix = new ak_ufix_DualResponse();
            G.U_DualResponse(ref fix, src, _st);
            if (!call) return 0;
            _fwd++;
            if (__d != 0) { if (_st.Marked == 0) __d = 0; else { __h.Root = src; _run->Defer = __d; } }
            rc = Abi.ak_uencode_DualResponse(_run, _ctx, &vt, &fix);
        }
        else
        {
            var fix = new ak_efix_DualResponse();
            G.E_DualResponse(ref fix, src, _st);
            if (!call) return 0;
            _fwd++;
            if (__d != 0) { if (_st.Marked == 0) __d = 0; else { __h.Root = src; _run->Defer = __d; } }
            rc = Abi.ak_encode_DualResponse(_run, _ctx, &vt, &fix);
        }
        _st.ReleasePins();   // D21 E1: the core has copied every pinned string
        if (__d != 0)
        {
            _run->Defer = 0;   // the next call starts from the default
            __h.Root = null;   // the context does not keep the message alive
#if AK_HOST_COUNT
            Stage.CountMarked += _st.Marked; Stage.CountPatched += _st.Patched; Stage.CountRepPatched += _st.RepPatched; Stage.CountMapPatched += _st.MapPatched;
#endif
            // E1R / E1C: every mark the fill left was patched by a frame before the core read it.
            if (!Stage.NoGuard && _st.Marked != _st.Patched && rc >= 0) rc = Abi.AK_ERR_HOST;
        }
        if (rc < 0) return (int)rc;
        if (_keep) return 0;   // EncodeInto: the output stays in the context (the move path)
        byte* bp; nuint blen;
        int tk = Abi.ak_enc_take(_ctx, &bp, &blen);
        if (tk != 0) return tk;
        outPtr = bp; outLen = (int)blen;
        return 0;
    }

    /// D26 (s15): the decode host context's native block, the push callbacks' `obj`: Host is the
    /// ONE GCHandle to the managed DecCtx, Buf the call's input, Arena the call's arena (null in drop mode).
    [StructLayout(LayoutKind.Sequential)]
    private struct DecRun { public IntPtr Host; public byte* Buf; public UnkArena* Arena; }

    /// D26 (s15): the host's explicit DECODE context, one per binding instance, created on its
    /// first decode and kept: it OWNS the core decode context (ak_dec_ctx_DualResponse, with its pvt
    /// bits), the native block DecRun (the push callbacks' `obj`) and ONE GCHandle to itself,
    /// allocated here (never per call), the native unknown-field options (`host` = the arena, grow's `sink`) and the arena. Per call: Begin sets Root (and Arena),
    /// the call runs, and Root, Buf and Arena are cleared after it. Freed in Dispose.
    private sealed class DecCtx : IDisposable
    {
        public IntPtr Ctx;
        public DecRun* Run;
        public UnkArena* Arena;
        public ak_dec_DualResponse_opts* Uo;
        public int Armed = int.MinValue;   // the `zero` the options at Uo were written for
        public DualResponse Root;
        private GCHandle _self;
        public DecCtx()
        {
            Ctx = Abi.ak_dec_ctx_new_DualResponse(null);   // rule 6: bound to this root, drop mode
            if (Ctx == IntPtr.Zero) throw new InvalidOperationException("ak_dec_ctx_new_DualResponse returned NULL");
            // D20: the pull family's bits, copied into this root-bound context (every bit: G.Str validates).
            int sp = Abi.ak_dec_set_pvt_DualResponse(Ctx, Pvt);   // step 5b: the root's one native pvt
            if (sp != 0) throw new InvalidOperationException("ak_dec_set_pvt_DualResponse: " + sp);
            // D23 / D24: the FSM's own D20 mask, copied once into the context when it is created.
            int fp = Abi.ak_fsm_set_pvt_DualResponse(Ctx, FsmPvt);
            if (fp != 0) throw new InvalidOperationException("ak_fsm_set_pvt_DualResponse: " + fp);
            _self = GCHandle.Alloc(this);
            Run = (DecRun*)NativeMemory.AllocZeroed((nuint)sizeof(DecRun));
            Run->Host = GCHandle.ToIntPtr(_self);
            Arena = UnkArena.Create();
            Uo = (ak_dec_DualResponse_opts*)NativeMemory.AllocZeroed((nuint)sizeof(ak_dec_DualResponse_opts));
        }
        public void Dispose()
        {
            if (Ctx != IntPtr.Zero) { Abi.ak_dec_ctx_free(Ctx); Ctx = IntPtr.Zero; }
            if (_self.IsAllocated) _self.Free();
            if (Run != null) { NativeMemory.Free(Run); Run = null; }
            if (Arena != null) { UnkArena.Destroy(Arena); Arena = null; }
            if (Uo != null) { NativeMemory.Free(Uo); Uo = null; }
            Root = null;
        }
    }

    private static DualResponse Tgt(void* obj) => ((DecCtx)GCHandle.FromIntPtr(((DecRun*)obj)->Host).Target).Root;

    [UnmanagedCallersOnly(CallConvs = new[] { typeof(CallConvCdecl) })]
    private static void ApplyRoot(IntPtr ctx, void* obj, ak_dfix_DualResponse* fix)
    {
        _rev++;
        try { if (G.PlantHostFail == 1) throw new InvalidOperationException("planted host failure (apply)"); G.D_DualResponse(ref *fix, Tgt(obj), ((DecRun*)obj)->Buf, ((DecRun*)obj)->Arena); }
        catch (DecoderFallbackException) { Abi.ak_fail(ctx, Abi.AK_ERR_TRANSCODE, null, 0); } catch { Abi.ak_fail(ctx, Abi.AK_ERR_HOST, null, 0); }
    }

    [UnmanagedCallersOnly(CallConvs = new[] { typeof(CallConvCdecl) })]
    private static void Add_left(IntPtr ctx, void* obj, long token, ak_dfix_Pair* xs, int n)
    {
        _rev++;
        try
        {
            if (G.PlantHostFail == 2) throw new InvalidOperationException("planted host failure (add)");
            byte* b = ((DecRun*)obj)->Buf;
            UnkArena* a = ((DecRun*)obj)->Arena;
            var lst = Tgt(obj).Left;
            lst.EnsureCapacity(lst.Count + n);   // step 9a: the run's count is known
            for (int i = 0; i < n; i++) { var x = new Pair(); G.D_Pair(ref xs[i], x, b, a); lst.Add(x); }
        }
        catch (DecoderFallbackException) { Abi.ak_fail(ctx, Abi.AK_ERR_TRANSCODE, null, 0); } catch { Abi.ak_fail(ctx, Abi.AK_ERR_HOST, null, 0); }
    }

    [UnmanagedCallersOnly(CallConvs = new[] { typeof(CallConvCdecl) })]
    private static void Add_right(IntPtr ctx, void* obj, long token, ak_dfix_Pair* xs, int n)
    {
        _rev++;
        try
        {
            if (G.PlantHostFail == 2) throw new InvalidOperationException("planted host failure (add)");
            byte* b = ((DecRun*)obj)->Buf;
            UnkArena* a = ((DecRun*)obj)->Arena;
            var lst = Tgt(obj).Right;
            lst.EnsureCapacity(lst.Count + n);   // step 9a: the run's count is known
            for (int i = 0; i < n; i++) { var x = new Pair(); G.D_Pair(ref xs[i], x, b, a); lst.Add(x); }
        }
        catch (DecoderFallbackException) { Abi.ak_fail(ctx, Abi.AK_ERR_TRANSCODE, null, 0); } catch { Abi.ak_fail(ctx, Abi.AK_ERR_HOST, null, 0); }
    }

    private static readonly byte[] One = new byte[1];

    /// Decision 11: every message position of this root, in plan.unk_positions order
    /// (the options' member order).
    public static readonly string[] UnkPositionNames = { "self", "left", "right" };

    /// A retained decode ended with a buffer grow handed out that no delivered group
    /// carried back to the host: a host defect, never a core code.
    public const int UNDELIVERED = -1001;
    public int Undelivered { get; private set; }
    /// The one reset that arms each decode (rule 7): a forward crossing, counted
    /// apart from ForwardCalls because the core's R5 counters do not count them.
    private static long _resets;
    public long ResetCalls => _resets;
    public const bool UnknownCompiledOut = false;

    /// D26: the decode host context (and with it the core decode context) is created on the
    /// first decode and kept for the binding's life.
    private void EnsureDec() { if (_dh == null) _dh = new DecCtx(); }

    /// The options, rewritten before every retained decode: every entry names the one
    /// grow and holds no pre-allocated buffer (all from grow, so the core never needs
    /// a refill); `zero` >= 0 leaves that position's entry all zero (DISCARD).
    private ak_dec_DualResponse_opts* Arm(int zero)
    {
        // Step a2 (iii): rewritten only when the mode changed. The core never writes a
        // grow-only entry (it takes and clears pre-placed buffers only, and there are none).
        var h = _dh;
        if (h.Armed == zero) return h.Uo;
        var uo = h.Uo;
        *uo = default;
        h.Armed = zero;
        uo->host = (IntPtr)h.Arena;   // D26: grow's `sink`, the decode host context's arena
        var g = UnkHost.Fn;
        if (zero != 0) uo->self.grow = g;
        if (zero != 1) uo->left.grow = g;
        if (zero != 2) uo->right.grow = g;
        return uo;
    }

    /// mode -2: drop (reset with NULL); -1: retain everywhere; k >= 0: retain but k.
    private int ArmFor(int mode)
    {
        Undelivered = 0;
        _resets++;
        var h = _dh;
        if (mode == -2) { h.Run->Arena = null; return Abi.ak_dec_reset_DualResponse(h.Ctx, null); }
        h.Arena->Begin();
        h.Run->Arena = h.Arena;   // the call's arena: the callbacks get it through `obj`
        return Abi.ak_dec_reset_DualResponse(h.Ctx, Arm(mode));
    }

    /// After every decode: a buffer still outstanding (the arena's count) after a success is
    /// UNDELIVERED. No reset here: decision 11 rule 7 (as amended 2026-09-26) takes ONE
    /// reset per decode, the arming one before it (ArmFor); the options stay at their
    /// stable native address (DecCtx.Uo) until the next decode's reset rewrites them.
    private int Disarm(int rc)
    {
        var a = _dh.Run->Arena;
        _dh.Run->Arena = null;
        if (a == null || a->Outstanding == 0) return rc;
        int left = a->Outstanding;   // the memory stays the arena's, rewound by the next Begin
        if (rc < 0) return rc;
        Undelivered = left;
        return UNDELIVERED;
    }

    /// The zeroed-position control's expectation: the facade bags at `position` cleared.
    public static void ClearPosition(DualResponse t, int position)
    {
        switch (position)
        {
            case 0:
            {
                t.UnknownFields = null;
                break;
            }
            case 1:
            {
                if (t.Left != null) foreach (var e0 in t.Left)
                {
                    e0.UnknownFields = null;
                }
                break;
            }
            case 2:
            {
                if (t.Right != null) foreach (var e0 in t.Right)
                {
                    e0.UnknownFields = null;
                }
                break;
            }
            default: throw new ArgumentOutOfRangeException(nameof(position));
        }
    }

    public DualResponse Decode(byte[] src, int len) { int rc = TryDecode(src, len, false, out var t); if (rc < 0) throw new InvalidOperationException($"core decode failed: {rc}"); return t; }
    public DualResponse DecodeU(byte[] src, int len) { int rc = TryDecode(src, len, true, out var t); if (rc < 0) throw new InvalidOperationException($"core decode failed: {rc}"); return t; }

    /// The core's code (< 0) on failure; the output is then unspecified and discarded (R-G6).
    public int TryDecode(byte[] src, int len, bool retain, out DualResponse result) => DecodeArmed(src, len, retain ? -1 : -2, out result);

    /// A control (decision 11 DISCARD): retain everywhere except `position` (an index into
    /// UnkPositionNames), whose entry is all zero when armed.
    public int TryDecodeZeroing(byte[] src, int len, int position, out DualResponse result) => DecodeArmed(src, len, position, out result);

    /// Step 5b (owner, 2026-10-04): the push vtable, built ONCE per root and kept in native
    /// memory (NativeMemory.Alloc, never freed: one per root for the process), so no decode
    /// writes it and the GC cannot move it. Not a static field of the struct type taken by
    /// address: a non-primitive struct static lives in a boxed object on the GC heap, which
    /// compaction may move, so its address is not stable without a pin. The core only reads
    /// the vtable during the call.
    private static readonly ak_dvt_DualResponse* Vt = MakeVt();
    private static ak_dvt_DualResponse* MakeVt()
    {
        var v = (ak_dvt_DualResponse*)NativeMemory.AllocZeroed((nuint)sizeof(ak_dvt_DualResponse));
        v->utf8_skip = AkUtf8Skip.DualResponse_ALL;   // D20: every bit set, G.Str validates (strict)
        v->apply = &ApplyRoot;
        v->add_left = &Add_left;
        v->add_right = &Add_right;
        return v;
    }
    /// Step 5b: the pull family's bits, once per root in native memory (the setter copies them).
    private static readonly ak_pvt_DualResponse* Pvt = MakePvt();
    private static ak_pvt_DualResponse* MakePvt() { var v = (ak_pvt_DualResponse*)NativeMemory.AllocZeroed((nuint)sizeof(ak_pvt_DualResponse)); v->utf8_skip = AkUtf8Skip.DualResponse_ALL; return v; }
    private int DecodeArmed(byte[] src, int len, int mode, out DualResponse result)
    {
        result = null;
        EnsureDec();
        // Step a2 (i): no ak_dec_err_reset / ak_dec_err: ak_decode_* clears the context's
        // sticky slot on entry and returns it (a host failure reported through ak_fail
        // from a reverse call included), so its return value carries every error.
        int ar = ArmFor(mode);
        if (ar != 0) { Disarm(ar); return ar; }
        var target = new DualResponse();
        // D26: the decode host context's ONE GCHandle (allocated with it) reaches it; the
        // call's root is set on it here and cleared after the call.
        var h = _dh;
        h.Root = target;
        int rc = Abi.AK_ERR_HOST;
        try
        {
            fixed (byte* b0 = src)
            fixed (byte* one = One)
            {
                // (NULL, 0) is never handed to the core: an empty buffer is a valid pointer and 0.
                byte* b = len == 0 ? one : b0;
                h.Run->Buf = b;
                _fwd++;
                rc = Abi.ak_decode_DualResponse(h.Ctx, h.Run, b, (nuint)len, Vt);
            }
        }
        finally { h.Root = null; h.Run->Buf = null; rc = Disarm(rc); }
        if (rc < 0) return rc;
        result = target;
        return 0;
    }

    /// D21 s8 attribution (HARNESS ONLY): the same push decode through another vtable.
    /// kind 0 `parse`: every callback null but `new_<slot>` (NewZero: the core skips a non-leaf
    /// element whose `new_` is null), utf8_skip all bits (as the reference); kind 1 `noop`:
    /// every callback G.Noop (new_: NewZero); kind 2 `parse-validate`: kind 0 with utf8_skip 0
    /// (the core validates every string).
    public static readonly ak_dvt_DualResponse* VtParse = MakeVtAttr(0), VtNoop = MakeVtAttr(1), VtParseValidate = MakeVtAttr(2);
    private static ak_dvt_DualResponse* MakeVtAttr(int kind)
    {
        var v = (ak_dvt_DualResponse*)NativeMemory.AllocZeroed((nuint)sizeof(ak_dvt_DualResponse));
        v->utf8_skip = kind == 2 ? 0 : AkUtf8Skip.DualResponse_ALL;
        if (kind == 1) *(void**)&v->apply = G.NoopPtr;
        if (kind == 1) *(void**)&v->add_left = G.NoopPtr;
        if (kind == 1) *(void**)&v->add_right = G.NoopPtr;
        return v;
    }
    /// D21 s8 attribution (HARNESS ONLY): DecodeArmed through `vt`; the graph is the bare
    /// root (the callbacks build nothing) and buffers the callbacks did not take are not
    /// UNDELIVERED here (the arena rewinds at the next decode).
    public int DecodeVt(byte[] src, int len, bool retain, ak_dvt_DualResponse* vt)
    {
        EnsureDec();
        int ar = ArmFor(retain ? -1 : -2);
        if (ar != 0) { Disarm(ar); return ar; }
        int rc;
        fixed (byte* b0 = src)
        fixed (byte* one = One)
        {
            byte* b = len == 0 ? one : b0;
            _dh.Run->Buf = b;
            rc = Abi.ak_decode_DualResponse(_dh.Ctx, _dh.Run, b, (nuint)len, vt);
            _dh.Run->Buf = null;
        }
        rc = Disarm(rc);
        return rc == UNDELIVERED ? 0 : rc;
    }
    /// D21 s8 attribution (HARNESS ONLY): the pull family's parse alone (no replay).
    public int ParseOnly(byte[] src, int len, bool retain)
    {
        EnsureDec();
        int ar = ArmFor(retain ? -1 : -2);
        if (ar != 0) { Disarm(ar); return ar; }
        int rc;
        fixed (byte* b0 = src)
        fixed (byte* one = One)
            rc = Abi.ak_parse_DualResponse(_dh.Ctx, len == 0 ? one : b0, (nuint)len);
        rc = Disarm(rc);
        return rc == UNDELIVERED ? 0 : rc;
    }

    /// ABI v1 7.1's PULL family: parse into the context's record stream (no reverse
    /// call but grow), then replay it with the same group readers the push callbacks
    /// use. The context is armed exactly as for push.
    public DualResponse Pull(byte[] src, int len) { int rc = TryPull(src, len, false, out var t); if (rc < 0) throw new InvalidOperationException($"core parse failed: {rc}"); return t; }
    public DualResponse PullU(byte[] src, int len) { int rc = TryPull(src, len, true, out var t); if (rc < 0) throw new InvalidOperationException($"core parse failed: {rc}"); return t; }

    public int TryPull(byte[] src, int len, bool retain, out DualResponse result)
    {
        result = null;
        EnsureDec();
        int ar = ArmFor(retain ? -1 : -2);
        if (ar != 0) { Disarm(ar); return ar; }
        var t = new DualResponse();
        int rc = Abi.AK_ERR_HOST;
        try
        {
            fixed (byte* b0 = src)
            fixed (byte* one = One)
            {
                byte* b = len == 0 ? one : b0;
                _fwd++;
                rc = Abi.ak_parse_DualResponse(_dh.Ctx, b, (nuint)len);
                if (rc >= 0)
                {
                    byte* recs; nuint rlen;
                    _fwd++;
                    rc = Abi.ak_bdr_ptr(_dh.Ctx, &recs, &rlen);
                    if (rc == 0) { try { Replay(t, b, recs, (int)rlen, _dh.Run->Arena); } catch (DecoderFallbackException) { rc = Abi.AK_ERR_TRANSCODE; } }
                }
            }
        }
        finally { rc = Disarm(rc); }
        if (rc < 0) return rc;
        result = t;
        return 0;
    }

    private const uint OP_APPLY = 1, OP_ADD = 2, OP_NEW = 3, OP_APPLY_ELEM = 4;   // ak_bdr_rec.op
    private static void Replay(DualResponse t, byte* b, byte* p, int len, UnkArena* a)
    {
        int at = 0;
        while (len - at >= sizeof(ak_bdr_rec))
        {
            ref var r = ref *(ak_bdr_rec*)(p + at);
            byte* body = p + at + sizeof(ak_bdr_rec);
            at += sizeof(ak_bdr_rec) + (int)r.bytes;
            uint outer = r.slot >> 16, inner = r.slot & 0xFFFF;
            switch (r.op)
            {
                case OP_APPLY: G.D_DualResponse(ref *(ak_dfix_DualResponse*)body, t, b, a); break;
                case OP_ADD when outer == 0 && inner == 1:   // a root-level run
                {
                    var xs = (ak_dfix_Pair*)body; var lst = t.Left;
                    lst.EnsureCapacity(lst.Count + (int)r.n);   // step 9a: the run's count is known
                    for (int i = 0; i < (int)r.n; i++) { var x = new Pair(); G.D_Pair(ref xs[i], x, b, a); lst.Add(x); }
                    break;
                }
                case OP_ADD when outer == 0 && inner == 2:   // a root-level run
                {
                    var xs = (ak_dfix_Pair*)body; var lst = t.Right;
                    lst.EnsureCapacity(lst.Count + (int)r.n);   // step 9a: the run's count is known
                    for (int i = 0; i < (int)r.n; i++) { var x = new Pair(); G.D_Pair(ref xs[i], x, b, a); lst.Add(x); }
                    break;
                }
                default: break;
            }
        }
    }

    /// FIX-PLAN D23: the FSM decode family. ak_fsm_begin_DualResponse returns the first
    /// event, ak_fsm_next_DualResponse each next one, each RETURNING the event's op (>
    /// 0; the root APPLY is the last, the end) or an error (< 0); every event is
    /// consumed (FsmDispatch) before the next call, which may overwrite its payload.
    /// One `fixed` spans begin and every next (the core holds spans into the input
    /// until the end event). Arming, Disarm, retain ownership and the failure path are
    /// pull's; a failed decode's partial object is discarded.
    public DualResponse Fsm(byte[] src, int len) { int rc = TryFsm(src, len, false, out var t); if (rc < 0) throw new InvalidOperationException($"core FSM decode failed: {rc}"); return t; }
    public DualResponse FsmU(byte[] src, int len) { int rc = TryFsm(src, len, true, out var t); if (rc < 0) throw new InvalidOperationException($"core FSM decode failed: {rc}"); return t; }
    /// D23: the FSM's own D20 mask (every bit: G.Str validates), native, copied by its setter
    /// (ak_fsm_set_pvt_<Root>) once, when EnsureDec creates the context.
    private static readonly ak_pvt_DualResponse* FsmPvt = MakeFsmPvt();
    private static ak_pvt_DualResponse* MakeFsmPvt() { var v = (ak_pvt_DualResponse*)NativeMemory.AllocZeroed((nuint)sizeof(ak_pvt_DualResponse)); v->utf8_skip = AkUtf8Skip.DualResponse_ALL; return v; }

    public int TryFsm(byte[] src, int len, bool retain, out DualResponse result)
    {
        result = null;
        EnsureDec();
        int ar = ArmFor(retain ? -1 : -2);
        if (ar != 0) { Disarm(ar); return ar; }
        var t = new DualResponse();
        int rc = Abi.AK_ERR_HOST;
        try
        {
            fixed (byte* b0 = src)
            fixed (byte* one = One)
            {
                byte* b = len == 0 ? one : b0;
                ak_fsm_ev ev;
                _fwd++;
                UnkArena* a = _dh.Run->Arena;
                int op = Abi.ak_fsm_begin_DualResponse(_dh.Ctx, b, (nuint)len, &ev);
                try
                {
                    while (op > 0)
                    {
                        if (op == (int)Abi.AK_BDR_APPLY)
                        {
                            // The root group: always the last event, the end.
                            G.D_DualResponse(ref *(ak_dfix_DualResponse*)ev.data, t, b, a);
                            break;
                        }
                        FsmDispatch(t, b, (uint)op, &ev, a);
                        _fwd++;
                        op = Abi.ak_fsm_next_DualResponse(_dh.Ctx, &ev);
                    }
                    rc = op < 0 ? op : 0;
                }
                catch (DecoderFallbackException) { rc = Abi.AK_ERR_TRANSCODE; }
            }
        }
        finally { rc = Disarm(rc); }
        if (rc < 0) return rc;   // the partial object is dropped
        result = t;
        return 0;
    }

    /// D23: one non-final event, `op` the call's return (NEW, ADD, APPLY_ELEM; the root APPLY is the end event,
    /// handled by TryFsm). slot = outer << 16 | inner, pull's numbering: a root-level run
    /// is (0, slot), a non-leaf slot's element is (slot, 0) and its inner runs (slot, inner).
    private static void FsmDispatch(DualResponse t, byte* b, uint op, ak_fsm_ev* ev, UnkArena* a)
    {
        byte* d = (byte*)ev->data;
        switch (op)
        {
            case Abi.AK_BDR_ADD:
                switch (ev->slot)
                {
                    case 1u:   // a root-level run
                    {
                        var xs = (ak_dfix_Pair*)d; var lst = t.Left; int n = (int)ev->n;
                        lst.EnsureCapacity(lst.Count + n);
                        for (int i = 0; i < n; i++) { var x = new Pair(); G.D_Pair(ref xs[i], x, b, a); lst.Add(x); }
                        return;
                    }
                    case 2u:   // a root-level run
                    {
                        var xs = (ak_dfix_Pair*)d; var lst = t.Right; int n = (int)ev->n;
                        lst.EnsureCapacity(lst.Count + n);
                        for (int i = 0; i < n; i++) { var x = new Pair(); G.D_Pair(ref xs[i], x, b, a); lst.Add(x); }
                        return;
                    }
                }
                return;
        }
    }

    public long PullFootprint() => _dh == null ? 0 : (long)Abi.ak_bdr_footprint(_dh.Ctx);
    public AkCounters EncCounters() { AkCounters c; Abi.ak_enc_counters(_ctx, &c); return c; }
    public void EncCountersReset() => Abi.ak_enc_counters_reset(_ctx);
    public AkCounters DecCounters() { AkCounters c; if (_dh == null) return default; Abi.ak_dec_counters(_dh.Ctx, &c); return c; }
    public void DecCountersReset() { if (_dh != null) Abi.ak_dec_counters_reset(_dh.Ctx); }

    public void Dispose()
    {
        _eh.Dispose();
        _dh?.Dispose(); _dh = null;
    }
}

#endif
